#define GOLDEN_ANGLE 2.39996323
#define PI 3.1415926538

vec4 blur(sampler2D u_texture, vec2 uv, float resolution, float radius, vec2 dir) {

    vec4 filtered = vec4(0.0,0.0,0.0,0.0);
    float blur = radius/resolution; 

    filtered += texture(u_texture, vec2(uv.x - 4.0*blur*dir.x, uv.y - 4.0*blur*dir.y)) * 0.0162162162;
    filtered += texture(u_texture, vec2(uv.x - 3.0*blur*dir.x, uv.y - 3.0*blur*dir.y)) * 0.0540540541;
    filtered += texture(u_texture, vec2(uv.x - 2.0*blur*dir.x, uv.y - 2.0*blur*dir.y)) * 0.1216216216;
    filtered += texture(u_texture, vec2(uv.x - 1.0*blur*dir.x, uv.y - 1.0*blur*dir.y)) * 0.1945945946;    
    filtered += texture(u_texture, vec2(uv.x, uv.y)) * 0.2270270270;    
    filtered += texture(u_texture, vec2(uv.x + 1.0*blur*dir.x, uv.y + 1.0*blur*dir.y)) * 0.1945945946;
    filtered += texture(u_texture, vec2(uv.x + 2.0*blur*dir.x, uv.y + 2.0*blur*dir.y)) * 0.1216216216;
    filtered += texture(u_texture, vec2(uv.x + 3.0*blur*dir.x, uv.y + 3.0*blur*dir.y)) * 0.0540540541;
    filtered += texture(u_texture, vec2(uv.x + 4.0*blur*dir.x, uv.y + 4.0*blur*dir.y)) * 0.0162162162;

    return filtered;
}

vec2 rotate(vec2 v, float a) {
	float s = sin(a);
	float c = cos(a);
	mat2 m = mat2(c, s, -s, c);
	return m * v;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //SETTINGS!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!//
    //filter, 0 is no filter, 1 is filtered (SLOW)
    int Filter = 0;
    //type, 0 is point, 1 is directional, 2 is far
    int type = 2;
    //Shadow Fade, 0 off, 1 on
    int fade = 0;
    float fadePow = 2.0;
    //Penumbra Size
    float penumbra = 0.1;
    //Linear Samples
    int N = 128;
    //Penumbra Samples
    int NN = 64;
    //Shadow Distance
    float Distance = 1.0;
    //Shadow Opacity
    float sOpacity = 1.0;
    ///SETTINGS!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!//

    if (type == 2){ 
    penumbra*=1.0;
    }
    if (fade != 1){
    fadePow = 0.0;
    }

    vec2 lightSize = vec2(penumbra) * vec2(iResolution.y/iResolution.x,1.0);    
    vec2 uv = fragCoord/iResolution.xy;   


    vec4 blocker = texture(iChannel0, uv);
    vec4 image = blocker;
    float base = blocker.a;          
    float steps = (1.0/float(N))*Distance;
    vec4 shadow = vec4(1.0,1.0,1.0,1.0); 
    float shadowS = 0.0;
    vec4 preColor = vec4(1.0,1.0,1.0,1.0); 
    vec3 finalColor = vec3(1.0,1.0,1.0); 


    //sample penumbra
    for(float j=0.0; j<=float(NN)*GOLDEN_ANGLE; j+=GOLDEN_ANGLE){


    vec2 light = iFrame <= 0 ? vec2(0.0, 0.0) : iMouse.xy/iResolution.xy;

    //circular light sampling
    vec2 Loc = vec2(cos(j), sin(j));
    if (type == 0){
    light += Loc*lightSize;
    }else if (type == 1){ 
    //directional light sampling
    light = light - vec2(0.5,0.5);
    light += normalize(rotate(light,(PI/2.0)))*((j/GOLDEN_ANGLE)/float(NN))*lightSize*mix(-1.0,1.0,mod(j/GOLDEN_ANGLE,2.0));    
    }else{
    light = normalize(light - vec2(0.5,0.5));
    light += rotate(light,(PI/2.0))*((j/GOLDEN_ANGLE)/float(NN))*lightSize*mix(-1.0,1.0,mod(j/GOLDEN_ANGLE,2.0));      
    }



    //sample linearly
    for(float i=float(N); i>=0.0; i--){

    if (type == 0){
    if(Filter == 0){
    preColor =  texture(iChannel0, clamp((uv-light)*mix(1.0,0.,i*steps*pow(distance(uv,light),1.0))+light,vec2(0.0,0.0),vec2(1.0,1.0)) );
    }else{
    preColor =  blur(iChannel0, clamp((uv-light)*mix(1.0,0.,i*steps*pow(distance(uv,light),1.0))+light,vec2(0.0,0.0),vec2(1.0,1.0)),1.0, penumbra*0.025, vec2(iResolution.y/iResolution.x,1.0));
    }
    }else{
    if(Filter == 0){
    preColor = texture(iChannel0, clamp((uv+light*i*steps), vec2(0.0,0.0),vec2(1.0,1.0)));
    }else{
    preColor =  blur(iChannel0, clamp((uv+light*i*steps), vec2(0.0,0.0),vec2(1.0,1.0)),1.0, penumbra*0.25, vec2(iResolution.y/iResolution.x,1.0));;
    }
    }
    //shadow = mix(1.0, shadow, pow((1.0-(i/float(N))),1.0));



    shadow.a *= mix(1.0,1.0-preColor.a, pow((1.0-(i/float(N))),fadePow));
    finalColor = mix(preColor.rgb,finalColor,1.0-preColor.a);


    }
    //shadow /= ;
    //accumulate final shadow
    shadowS += shadow.a;
    shadow = vec4(1.0,1.0,1.0,1.0); ;
    }

    //normalize light
    shadowS /= float(NN);  
    //shadowS = pow(shadowS,1.0);
    //apply opacity    
    shadowS = mix(1.0,shadowS,sOpacity);


    // Output to screen
    fragColor = mix(vec4(0.0),image, clamp(shadowS+base,0.0,1.0));
    //fragColor = vec4(finalColor,1.0);

}
